contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint am, uint unlockTime) public payable {
        require(address(this).balance >= amount);
        require(am <= amount);
        require(amount >= 1 ether);

        c.Put{value: amount}(unlockTime);
        uint256 before = address(c).balance;
        uint256 myBefore = address(this).balance;

        bool reverted;
        try c.Collect{value: 0}(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(address(c).balance == before && address(this).balance == myBefore);
        } else {
            assert(address(this).balance == myBefore + am);
        }
    }

    receive() external payable {}
}

